// NodeServiceClient is a client for the agentcompose.v2.NodeService service.
type NodeServiceClient interface {
	// NodeConnect is the node's single outbound long-lived stream. The node is
	// the dialer; the server reverse-dispatches session commands over it.
	NodeConnect(context.Context) *connect.BidiStreamForClient[v2.NodeUpstreamFrame, v2.NodeDownstreamFrame]
	ListNodes(context.Context, *connect.Request[v2.ListNodesRequest]) (*connect.Response[v2.ListNodesResponse], error)
	GetPublicIPLookupConfig(context.Context, *connect.Request[v2.GetPublicIPLookupConfigRequest]) (*connect.Response[v2.NodePublicIPLookupConfig], error)
	UpdatePublicIPLookupConfig(context.Context, *connect.Request[v2.UpdatePublicIPLookupConfigRequest]) (*connect.Response[v2.NodePublicIPLookupConfig], error)
	GetNodeProxyConfig(context.Context, *connect.Request[v2.GetNodeProxyConfigRequest]) (*connect.Response[v2.NodeProxyConfig], error)
	UpdateNodeProxyConfig(context.Context, *connect.Request[v2.UpdateNodeProxyConfigRequest]) (*connect.Response[v2.NodeProxyConfig], error)
	SetNodeLastProxy(context.Context, *connect.Request[v2.SetNodeLastProxyRequest]) (*connect.Response[v2.SetNodeLastProxyResponse], error)
	SetNodeCapacity(context.Context, *connect.Request[v2.SetNodeCapacityRequest]) (*connect.Response[v2.SetNodeCapacityResponse], error)
	MoveNode(context.Context, *connect.Request[v2.MoveNodeRequest]) (*connect.Response[v2.MoveNodeResponse], error)
	ManageEditor(context.Context, *connect.Request[v2.ManageEditorRequest]) (*connect.Response[v2.ManageEditorResponse], error)
	// ManageNodeEnvironment creates or removes one named shared environment on a
	// node host. The environment is a persistent HOME a session can run against
	// (env_mode="shared"), so installed dependencies and CLI login state outlive
	// any single task. The node owns the on-disk layout; this call carries only
	// the id. Create is idempotent.
	ManageNodeEnvironment(context.Context, *connect.Request[v2.ManageNodeEnvironmentRequest]) (*connect.Response[v2.ManageNodeEnvironmentResponse], error)
	// SyncNodeEnvironment installs the exact desired skill/plugin set into a shared
	// environment's HOME (environment maintenance — the real install/uninstall).
	SyncNodeEnvironment(context.Context, *connect.Request[v2.SyncNodeEnvironmentRequest]) (*connect.Response[v2.SyncNodeEnvironmentResponse], error)
	// InspectNodeEnvironment reports what is physically installed in an
	// environment HOME so the caller can diff it against the configured set.
	InspectNodeEnvironment(context.Context, *connect.Request[v2.InspectNodeEnvironmentRequest]) (*connect.Response[v2.InspectNodeEnvironmentResponse], error)
	// InspectNodeSystemEnv enumerates the skill/plugin/MCP the providers discover
	// in the node operator's REAL HOME (env_mode="system"). Read-only; this is what
	// makes a system-env session's actual capability set visible.
	InspectNodeSystemEnv(context.Context, *connect.Request[v2.InspectNodeSystemEnvRequest]) (*connect.Response[v2.InspectNodeSystemEnvResponse], error)
	// SyncNodeSystemEnv installs platform resources into that HOME incrementally,
	// and removes ONLY entries the platform installed. It never prunes, so the
	// operator's own resources cannot be deleted through it.
	SyncNodeSystemEnv(context.Context, *connect.Request[v2.SyncNodeSystemEnvRequest]) (*connect.Response[v2.SyncNodeSystemEnvResponse], error)
	// ArchiveNodeSystemEnvResource tars one resource out of that HOME and uploads
	// it back so a locally installed skill/plugin can enter the platform library.
	ArchiveNodeSystemEnvResource(context.Context, *connect.Request[v2.ArchiveNodeSystemEnvResourceRequest]) (*connect.Response[v2.ArchiveNodeSystemEnvResourceResponse], error)
	SelfUpgradeNode(context.Context, *connect.Request[v2.SelfUpgradeNodeRequest]) (*connect.Response[v2.SelfUpgradeNodeResponse], error)
	RuntimeUpgradeNode(context.Context, *connect.Request[v2.RuntimeUpgradeNodeRequest]) (*connect.Response[v2.RuntimeUpgradeNodeResponse], error)
	HostExec(context.Context, *connect.Request[v2.HostExecRequest]) (*connect.Response[v2.HostExecResponse], error)
	// HostFileUpload streams one chunk of a file upload to a node host. The
	// caller splits the file into bounded chunks and sends one unary request per
	// chunk (upload_id correlates them); the node appends to a temp file and
	// atomically renames on the final chunk after verifying size+sha256.
	HostFileUpload(context.Context, *connect.Request[v2.HostFileUploadRequest]) (*connect.Response[v2.HostFileUploadResponse], error)
	ApproveNode(context.Context, *connect.Request[v2.ApproveNodeRequest]) (*connect.Response[v2.ApproveNodeResponse], error)
	RevokeNode(context.Context, *connect.Request[v2.RevokeNodeRequest]) (*connect.Response[v2.RevokeNodeResponse], error)
	// DeleteNode permanently removes a node record (any status) and drops its live
	// connection. Unlike RevokeNode — which keeps the record in a revoked state
	// for audit — this is a hard delete: the record and its sealed credential are
	// gone. An online node is refused unless force is set; a management node that
	// still owns execution nodes is always refused (delete or reassign its
	// execution nodes first) so it cannot orphan them.
	DeleteNode(context.Context, *connect.Request[v2.DeleteNodeRequest]) (*connect.Response[v2.DeleteNodeResponse], error)
	// OnboardNode provisions a new node. For the execution role it pre-creates a
	// pending record, mints a per-node TOTP secret, and returns the secret + a
	// ready-to-run install command; manager_node_id is REQUIRED and must name an
	// existing management node that owns it. For the management role it creates a
	// passive ownership container: approved and online immediately, with no secret
	// and no client process (it only groups execution nodes).
	OnboardNode(context.Context, *connect.Request[v2.OnboardNodeRequest]) (*connect.Response[v2.OnboardNodeResponse], error)
	// RevokeOnboardNode closes the onboarding loop: for a node that has not yet
	// registered it deletes the pending record and invalidates the token; for a
	// node that already registered it revokes it (like RevokeNode) and drops the
	// live connection. Idempotent.
	RevokeOnboardNode(context.Context, *connect.Request[v2.RevokeOnboardNodeRequest]) (*connect.Response[v2.RevokeOnboardNodeResponse], error)
	// DispatchSession places a session on a connected node: the server picks (or
	// is told) a node, reverse-dispatches a CreateSession command over that node's
	// NodeConnect stream, waits for the node's ack, and persists the session→node
	// binding. This is the phase-1 standalone dispatch entrypoint; it does not go
	// through the run controller.
	DispatchSession(context.Context, *connect.Request[v2.DispatchSessionRequest]) (*connect.Response[v2.DispatchSessionResponse], error)
	// DeleteNodeSession tears a session down on its owning node and clears the
	// binding.
	DeleteNodeSession(context.Context, *connect.Request[v2.DeleteNodeSessionRequest]) (*connect.Response[v2.DeleteNodeSessionResponse], error)
	// FollowNodeSession streams a session's output/result frames as the owning
	// node reports them upstream. Used to watch a dispatched task live.
	FollowNodeSession(context.Context, *connect.Request[v2.FollowNodeSessionRequest]) (*connect.ServerStreamForClient[v2.NodeSessionEvent], error)
	// SendSessionInput delivers a user turn (or EOF) into an interactive session's
	// running provider process on its owning node. Multi-turn currently supports
	// the codex provider.
	SendSessionInput(context.Context, *connect.Request[v2.SendSessionInputRequest]) (*connect.Response[v2.SendSessionInputResponse], error)
	// ── Split-config session control (each reverse-dispatches a downstream command
	// to the session's owning node and returns the node's config ack). The server
	// assigns the monotonic revision; the node reports applied/effective revision
	// and whether a runtime restart is needed to make the change live. ──
	//
	// ConfigureNodeSessionLLM points the session's editor directly at an LLM
	// service (no server proxy) by writing the provider-specific config/env.
	ConfigureNodeSessionLLM(context.Context, *connect.Request[v2.ConfigureNodeSessionLLMRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// ApplyNodeSessionMCPs sets the full desired MCP server set for a session.
	ApplyNodeSessionMCPs(context.Context, *connect.Request[v2.ApplyNodeSessionMCPsRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// ApplyNodeSessionSkills sets the full desired skill set for a session.
	ApplyNodeSessionSkills(context.Context, *connect.Request[v2.ApplyNodeSessionSkillsRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// ApplyNodeSessionPlugins sets the full desired plugin set for a session.
	ApplyNodeSessionPlugins(context.Context, *connect.Request[v2.ApplyNodeSessionPluginsRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// ConfigureNodeSessionMode selects the editor's permission/approval mode.
	ConfigureNodeSessionMode(context.Context, *connect.Request[v2.ConfigureNodeSessionModeRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// StartNodeSessionRuntime starts a session created with defer_start.
	StartNodeSessionRuntime(context.Context, *connect.Request[v2.StartNodeSessionRuntimeRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// RestartNodeSessionRuntime restarts the editor to apply pending config.
	RestartNodeSessionRuntime(context.Context, *connect.Request[v2.RestartNodeSessionRuntimeRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
	// CollectNodeSessionArtifacts asks the node to package the session workspace
	// for retrieval through the tunnel.
	CollectNodeSessionArtifacts(context.Context, *connect.Request[v2.CollectNodeSessionArtifactsRequest]) (*connect.Response[v2.NodeSessionConfigAck], error)
}

